content.text:
            return Err("illegal initial configuration".into());
        }
        let tb = task.template * self.words;
        let gb = group * self.nodes;
        for word in 0..self.words {
            let mut bits = self.tmpl_fp[tb + word];
            while bits != 0 {
                let node = word * 64 + bits.trailing_zeros() as usize;
                bits &= bits - 1;
                if self.g_ref[gb + node] == 0 {
                    self.g_fp[group * self.words + word] |= 1u64 << (node % 64);
                    self.g_fpc[group] += 1;
                }
                self.g_ref[gb + node] += 1;
            }
        }
    }

    for group in 0..self.groups {
        if self.g_cnt[group] == 0 {
            continue;
        }
        self.active += 1;
        if self.quota[group] == 0 || !self.works(group) {
            return Err("illegal initial configuration".into());
        }
    }

    for node in 0..self.nodes {
        let mut used = 0u64;
        for group in 0..self.groups {
            if self.g_ref[group * self.nodes + node] > 0 {
                used = used.checked_add(self.quota[group]).ok_or("reserve overflow")?;
            }
        }
        self.usage[node] = used;
        self.slots += used as i64;
        if used > self.caps[node] {
            return Err("illegal initial configuration".into());
        }
    }
    Ok(())
}

#[inline]
fn works(&self, group: usize) -> bool {
    (self.g_load[group] as u128) <= (self.quota[group] as u128) * (self.budget[group] as u128)
}

/// Recomputes the derived proposal row of one dirty group.
fn evaluate_group(&mut self, group: usize) {
    let n = self.nodes;
    let w = self.words;
    let gb = group * n;
    let gwb = group * w;
    let outs = std::mem::take(&mut self.outs[group]);
    let ins = std::mem::take(&mut self.ins[group]);

    self.p_ref[gb..gb + n].copy_from_slice(&self.g_ref[gb..gb + n]);
    for word in 0..w {
        self.p_fp[gwb + word] = 0;
    }

    for &task in &outs {
        let tb = self.tasks[task].template * w;
        for word in 0..w {
            let mut bits = self.tmpl_fp[tb + word];
            while bits != 0 {
                let node = word * 64 + bits.trailing_zeros() as usize;
                bits &= bits - 1;
                self.p_ref[gb + node] -= 1;
            }
        }
    }
    for &task in &ins {
        let tb = self.tk_temp[task] as usize * w;
        for word in 0..w {
            let mut bits = self.tmpl_fp[tb + word];
            while bits != 0 {
                let node = word * 64 + bits.trailing_zeros() as usize;
                bits &= bits - 1;
                self.p_ref[gb + node] += 1;
            }
        }
    }

    let mut fpc = 0u32;
    for node in 0..n {
        if self.p_ref[gb + node] > 0 {
            self.p_fp[gwb + node / 64] |= 1u64 << (node % 64);
            fpc += 1;
        }
    }
    self.p_fpc[group] = fpc;

    let mut out_weight = 0u64;
    for &task in &outs {
        out_weight += self.tasks[task].weight;
    }
    let mut in_weight = 0u64;
    for &task in &ins {
        in_weight += self.tk_weight[task];
    }
    let retained = self.g_cnt[group] as usize - outs.len();
    self.p_cnt[group] = (retained + ins.len()) as u32;
    self.p_load[group] = self.g_load[group] - out_weight + in_weight;

    // Members that no edit touched all shared the committed group key, so
    // the proposal key multiset is that key (when at least one such member
    // stays) plus the key of every task assigned to this group.
    self.keys.clear();
    self.keys.reserve(ins.len());
    for &task in &ins {
        self.keys.push((self.tmpl_dom[self.tk_temp[task] as usize], self.tk_class[task]));
    }
    self.keys.sort_unstable();
    self.keys.dedup();
    let base = (self.g_key_d[group], self.g_key_c[group]);
    let keeps_base = retained > 0;
    let base_present = keeps_base && self.keys.binary_search(&base).is_ok();
    let distinct = self.keys.len() + if keeps_base && !base_present { 1 } else { 0 };
    self.p_mixed[group] = if distinct > 1 { 1 } else { 0 };
    if distinct == 1 {
        let key = if self.keys.len() == 1 { self.keys[0] } else { base };
        self.p_key_d[group] = key.0;
        self.p_key_c[group] = key.1;
    } else {
        self.p_key_d[group] = 0;
        self.p_key_c[group] = 0;
    }

    let quota = self.pq_quota[group];
    let budget = self.pq_budget[group];
    let load = self.p_load[group] as u128;
    self.p_work[group] =
        if self.p_cnt[group] > 0 && (quota == 0 || load > quota as u128 * budget as u128) {
            1
        } else {
            0
        };

    // reservation delta over the symmetric difference of footprints
    let old_quota = self.quota[group] as i64;
    let new_quota = quota as i64;
    for word in 0..w {
        let mut bits = self.g_fp[gwb + word];
        while bits != 0 {
            let node = word * 64 + bits.trailing_zeros() as usize;
            bits &= bits - 1;
            if node < n {
                self.touch_node(node);
                self.delta[node] -= old_quota;
            }
        }
    }
    for word in 0..w {
        let mut bits = self.p_fp[gwb + word];
        while bits != 0 {
            let node = word * 64 + bits.trailing_zeros() as usize;
            bits &= bits - 1;
            if node < n {
                self.touch_node(node);
                self.delta[node] += new_quota;
            }
        }
    }

    self.outs[group] = outs;
    self.ins[group] = ins;
}

fn touch_node(&mut self, node: usize) {
    if self.nd_mark[node] != self.stamp {
        self.nd_mark[node] = self.stamp;
        self.delta[node] = 0;
        self.pcap[node] = self.caps[node];
        self.affected.push(node);
    }
}

